mapper.sql:
WHERE deal_year_month = #{searchParam.dealYearMonth}

    AND (
        display_name LIKE CONCAT('%', #{searchParam.keyword}, '%')
        OR address LIKE CONCAT('%', #{searchParam.keyword}, '%')
        OR umd_name LIKE CONCAT('%', #{searchParam.keyword}, '%')
        OR sgg_name LIKE CONCAT('%', #{searchParam.keyword}, '%')
    )


    AND sgg_name = #{searchParam.sggName}


    AND umd_name = #{searchParam.umdName}


    AND property_category = #{searchParam.propertyCategory}


    AND transaction_type = #{searchParam.transactionType}


    AND (CASE
        WHEN transaction_type = 'trade' THEN trade_amount_manwon
        ELSE deposit_amount_manwon
    END) >= #{searchParam.minAmount}


    AND (CASE
        WHEN transaction_type = 'trade' THEN trade_amount_manwon
        ELSE deposit_amount_manwon
    END) <= #{searchParam.maxAmount}


    AND area_pyeong >= #{searchParam.minAreaPyeong}


    AND area_pyeong <= #{searchParam.maxAreaPyeong}


    AND build_year >= #{searchParam.minBuildYear}


    AND build_year <= #{searchParam.maxBuildYear}

mapper.select:
SELECT DISTINCT umd_name FROM real_estate_transactions WHERE deal_year_month = #{dealYearMonth} AND umd_name IS NOT NULL AND umd_name != ''
AND sgg_name = #{sggName}
ORDER BY umd_name ASC

SELECT MONTH(deal_date) AS dealMonth, ROUND(AVG(
deposit_amount_manwon trade_amount_manwon
), 0) AS averageAmount, MIN(
deposit_amount_manwon trade_amount_manwon
) AS minAmount, MAX(
deposit_amount_manwon trade_amount_manwon
) AS maxAmount, COUNT(*) AS transactionCount FROM real_estate_transactions WHERE property_match_key = #{propertyMatchKey} AND YEAR(deal_date) = #{year} AND (
deposit_amount_manwon trade_amount_manwon
) > 0 GROUP BY MONTH(deal_date) ORDER BY MONTH(deal_date)

SELECT

FROM real_estate_transactions
WHERE property_match_key = #{propertyMatchKey}
  AND id != #{excludeId}
ORDER BY deal_date DESC, id DESC
LIMIT #{limit}

SELECT

FROM real_estate_transactions
WHERE id != #{property.id}
  AND property_match_key != #{property.propertyMatchKey}
  AND sgg_name = #{property.sggName}
  AND umd_name = #{property.umdName}
  AND property_category = #{property.propertyCategory}
  AND transaction_type = #{property.transactionType}

  AND area_m2 > 0
  AND area_m2 BETWEEN #{property.areaM2} * 0.85 AND #{property.areaM2} * 1.15


  AND build_year BETWEEN #{property.buildYear} - 10 AND #{property.buildYear} + 10

ORDER BY deal_date DESC, id DESC
LIMIT #{limit}
